import{_ as t,o as a,c as s,a2 as i}from"./chunks/framework.Bg-Zxr5O.js";const m=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"manual-en/RELIABILITY.md","filePath":"manual-en/RELIABILITY.md","lastUpdated":1785684581000}'),o={name:"manual-en/RELIABILITY.md"};function n(d,e,l,r,h,c){return a(),s("div",null,[...e[0]||(e[0]=[i(`<h3 id="_15-18-reliability" tabindex="-1">15.18 RELIABILITY <a class="header-anchor" href="#_15-18-reliability" aria-label="Permalink to &quot;15.18 RELIABILITY&quot;">​</a></h3><pre><code>RELIABILITY
        /VARIABLES=var_list
        /SCALE (name) = {var_list, ALL}
        /MODEL={ALPHA, SPLIT[(n)]}
        /SUMMARY={TOTAL,ALL}
        /MISSING={EXCLUDE,INCLUDE}
</code></pre><p>The <code>RELIABILITY</code> command performs reliability analysis on the data.</p><p>The <code>VARIABLES</code> subcommand is required. It determines the set of variables upon which analysis is to be performed.</p><p>The <code>SCALE</code> subcommand determines the variables for which reliability is to be calculated. If <code>SCALE</code> is omitted, then analysis for all variables named in the <code>VARIABLES</code> subcommand are used. Optionally, the name parameter may be specified to set a string name for the scale.</p><p>The <code>MODEL</code> subcommand determines the type of analysis. If <code>ALPHA</code> is specified, then Cronbach’s Alpha is calculated for the scale. If the model is <code>SPLIT</code>, then the variables are divided into 2 subsets. An optional parameter n may be given, to specify how many variables to be in the first subset. If n is omitted, then it defaults to one half of the variables in the scale, or one half minus one if there are an odd number of variables. The default model is <code>ALPHA</code>.</p><p>By default, any cases with user missing, or system missing values for any variables given in the <code>VARIABLES</code> subcommand are omitted from the analysis. The <code>MISSING</code> subcommand determines whether user missing values are included or excluded in the analysis.</p><p>The <code>SUMMARY</code> subcommand determines the type of summary analysis to be performed. Currently there is only one type: <code>SUMMARY=TOTAL</code>, which displays per-item analysis tested against the totals.</p><h4 id="_15-18-1-example-reliability" tabindex="-1">15.18.1 Example - Reliability <a class="header-anchor" href="#_15-18-1-example-reliability" aria-label="Permalink to &quot;15.18.1 Example - Reliability&quot;">​</a></h4><p>Before analysing the results of a survey – particularly for a multiple choice survey – it is desireable to know whether the respondents have considered their answers or simply provided random answers.</p><p>In the following example the survey results from the file hotel.sav are used. All five survey questions are included in the reliability analysis. However, before running the analysis, the data must be preprocessed. An examination of the survey questions reveals that two questions, <em>viz:</em> v3 and v5 are negatively worded, whereas the others are positively worded. All questions must be based upon the same scale for the analysis to be meaningful. One could use the <code>RECODE</code> command (see <a href="./RECODE">RECODE</a>), however a simpler way is to use <code>COMPUTE</code> (see <a href="./COMPUTE">COMPUTE</a>) and this is what is done in Example 15.8.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>get file=&quot;hotel.sav&quot;.  * Recode V3 and V5 inverting the sense of the values. compute v3 = 6 - v3. compute v5 = 6 - v5.  reliability 	/variables= all 	/model=alpha.</span></span></code></pre></div><p><strong>Example 15.8:</strong> Investigating the reliability of survey responses</p><p>In this case, all variables in the data set are used. So we can use the special keyword ‘ALL’ (see <a href="./BNF">BNF</a>).</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span></span></span></code></pre></div><p><strong>Screenshot 15.8:</strong> Reliability dialog box with all variables selected</p><p>Result 15.6 shows that Cronbach’s Alpha is 0.11 which is a value normally considered too low to indicate consistency within the data. This is possibly due to the small number of survey questions. The survey should be redesigned before serious use of the results are applied.</p><table tabindex="0"><thead><tr><th>Cases</th><th>N</th><th>Percent</th></tr></thead><tbody><tr><td>Valid</td><td>17</td><td>100.0%</td></tr><tr><td>Excluded</td><td>0</td><td>.0%</td></tr><tr><td>Total</td><td>17</td><td>100.0%</td></tr><tr><td>Cronbach&#39;s Alpha</td><td>N of Items</td><td></td></tr><tr><td>.11</td><td>5</td><td></td></tr></tbody></table><p><strong>Result 15.6:</strong> The results of the reliability command on hotel.sav</p>`,19)])])}const u=t(o,[["render",n]]);export{m as __pageData,u as default};
